def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_live_bid = 0.0
    cindy_alive = False
    cindy_bid = None

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > strong_live_bid:
                    strong_live_bid = float(bid)
            if oid == 'Cindy':
                cindy_alive = True
                if bid is not None:
                    cindy_bid = float(bid)

    if not alive:
        return float(min(budget, 18.0))

    ratio = supply / float(WATER_REQ)
    very_tight = ratio < 1.35
    tight = ratio < 1.6
    comfortable = ratio >= 1.8

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1
    if day >= 8:
        urgency += 1

    if cindy_alive and cindy_bid is not None and cindy_bid >= 150 and urgency <= 1 and not very_tight:
        return float(min(budget, 6.0 if comfortable else 12.0))

    target = 0.0

    if urgency >= 5:
        target = 0.96 * DAILY_SALARY
        if cindy_bid is not None and cindy_bid < 0.9 * DAILY_SALARY:
            target = max(target, cindy_bid + 3.0)
    elif urgency >= 3:
        if very_tight:
            target = max(0.88 * DAILY_SALARY, strong_live_bid + 2.5)
        elif tight:
            target = max(0.72 * DAILY_SALARY, min(strong_live_bid + 1.5, 0.9 * DAILY_SALARY))
        else:
            target = 0.52 * DAILY_SALARY
    else:
        if very_tight:
            if strong_live_bid > 0:
                if strong_live_bid <= 70:
                    target = max(48.0, strong_live_bid + 1.2)
                elif strong_live_bid <= 110:
                    target = min(76.0, strong_live_bid + 1.0)
                else:
                    target = 14.0
            else:
                target = 46.0
        elif tight:
            if cindy_bid is not None and cindy_bid >= 140:
                target = 10.0
            else:
                target = 28.0 if comfortable else 34.0
        else:
            target = 8.0 if cindy_alive else 18.0

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if urgency <= 1 and days_left >= 3:
        reserve_floor = 20.0
    bid = min(budget, target)
    if budget - bid < reserve_floor:
        bid = max(0.0, budget - reserve_floor)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, 63.0))

    return float(max(0.0, round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace (immediate reaction only)
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else 0.0

    # Aggression inference: if someone bid very high yesterday, others likely are contesting.
    # Use supply to scale aggressiveness: with higher supply, we can pay less to still get water.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base target bid band from yesterday.
    # If high contest yesterday, bid around (highest_prev_bid - small offset) to win enough.
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        # Contested environment
        if hp <= 2 or no_water_days >= 2:
            target = min(budget, DAILY_SALARY * (0.95 - 0.1 * supply_ratio))
        else:
            # Slightly under the top bidder to conserve budget
            target = min(budget, max(0.0, highest_prev_bid * 0.92 - 2.0))
    else:
        # Less contested
        if hp <= 2 or no_water_days >= 2:
            target = min(budget, DAILY_SALARY * (0.8 - 0.05 * supply_ratio))
        else:
            # Aim to secure water without overpaying
            # Use second_prev_bid as a proxy for typical bids.
            base = second_prev_bid if second_prev_bid > 0 else (DAILY_SALARY * 0.55)
            target = min(budget, max(0.0, base * (0.85 + 0.1 * supply_ratio)))

    # Ensure we don't bid negative and keep within budget.
    target = max(0.0, min(float(budget), float(target)))

    # If budget is extremely low, bid everything.
    if budget <= 5.0:
        return max(0.0, float(budget))

    return target
